def fix_french(text: str) -> str:
    for old, new in PHRASE_FIXES:
        text = text.replace(old, new)
    for old, new in WORD_FIXES:
        text = text.replace(old, new)
    # Do not blanket-replace CORRUPT before phrase fixes above.
    # Remaining placeholder bytes are fixed explicitly below.
    for a, b in [
        ("au-delé", "au-delà"),
        ("Médiathéque", "Médiathèque"),
        ("écosystéme", "écosystème"),
        ("éQUIPEPS", "ÉQUIPEPS"),
        (" —  Sport", " — Sport"),
        ("</strong> é Xavier", "</strong> — Xavier"),
        ("&raquo; é Xavier", "&raquo; — Xavier"),
        ("il il revient", "il revient"),
        ("oé le", "où le"),
        ("toujours é créer", "toujours à créer"),
        ("expérience é il", "expérience — il"),
        ("YouTube é chaque", "YouTube — chaque"),
        ("handball é le", "handball — le"),
        ("é première", "À première"),
        ("réle", "rôle"),
        ("é Sport Pro", "— Sport Pro"),
        ("paysage é Sport", "paysage — Sport"),
        ("Marseille é aboutissement", "Marseille — aboutissement"),
        ("partenaire é organisation", "partenaire — organisation"),
        ("équipements é elle", "équipements — elle"),
        ("2026–2027 é Les", "2026–2027 « Les"),
        ("<h3>écosystème", "<h3>Écosystème"),
        ("<p>écosystème", "<p>Écosystème"),
        ("établissements</span>", "Établissements</span>"),
    ]:
        text = text.replace(a, b)
    # Last resort: stray placeholders -> é (middle of words only; À/à/— handled above).
    if CORRUPT in text:
        text = text.replace(CORRUPT, "é")
    if "Proposition-BEST-SELLER.pdf" not in text:
        anchor = '<a href="assets/Post%20linkedin%20sportprogroup.pdf" class="download-link" target="_blank">PDF LinkedIn</a>'
        repl = anchor + "\n          " + '<a href="assets/Proposition-BEST-SELLER.pdf" class="download-link" target="_blank">PDF Proposition</a>'
        text = text.replace(anchor, repl)
    return text


def build_html() -> str:
    return fix_french(_INDEX_TEMPLATE)


def main() -> None:
    html = build_html()
    OUTPUT_HTML.write_text(html, encoding="utf-8")
    size = OUTPUT_HTML.stat().st_size
    print(f"Generated: {OUTPUT_HTML}")
    print(f"Size: {size} bytes")


if __name__ == "__main__":
    main()
